from pyspark.sql import functions as F


def solve(checkout_events):
    repeats = F.filter("items", lambda x: x["qty"] > 2)
    return checkout_events.select(
        "event_id",
        "step",
        F.transform(repeats, lambda x: x["sku"]).alias("repeat_skus"),
        F.forall("items", lambda x: x["price"] >= 150).alias("has_premium"),
    )
